// Кейс: .qa/tests/monitoring/MON-021.md · план: .qa/e2e-app/specs/app.md (1.22)
// Телефон неподвижен BANCI_MONITOR_MINUTES минут (по умолчанию 5) во время мониторинга → ни разу нет «המכשיר זז»,
// статус «תקין», таймер растёт → «כבה את המצלמה» → итог. («מה רצוי» #8d2595: טלפון שמונח במקום ולא זז לא מקבל «המכשיר זז».)
// Ложные тревоги «זוהתה סכנה בבריכה» — отдельный реджект #18bb68: НЕ провал, только лог и скриншот.
// ЗАПУСКАЕТ МОНИТОРИНГ (сеанс в «היסטוריה») — только с BANCI_MONITORING=1. Телефон не трогать весь прогон.
import { by, assert } from '../../lib/appium.mjs';
import {
  requireMonitoringOptIn, startMonitoring, endMonitoring, timerSeconds,
  movedVisible, MOVED, logDangerAlarm, dangerClosed, dismissFalseDanger,
} from '../../lib/monitoring.mjs';

export const name = 'Неподвижный телефон N минут мониторинга: нет «המכשיר זז», статус «תקין» #8d2595 @iphone @app @data';

export default async function (app) {
  requireMonitoringOptIn();
  const minutes = Number(process.env.BANCI_MONITOR_MINUTES || 5);
  await startMonitoring(app);

  const target = minutes * 60;
  const end = Date.now() + target * 1000 + 60000;
  const alarms = [];
  let prev = await timerSeconds(app);
  while (prev < target) {
    assert(Date.now() < end, `таймер дошёл до ${target} с за отведённое время (сейчас ${prev} с)`);
    await new Promise((r) => setTimeout(r, 2000)); // интервал опроса состояния, не ожидание результата
    assert((await app.appState()) === 4, 'Banci на переднем плане, не упала');
    if (await movedVisible(app)) {
      const shot = await app.screenshot('8d2595-still-false-moved').catch(() => undefined);
      assert(false, `телефон неподвижен — «${MOVED}» не появляется (появилось на ~${prev} с мониторинга, скрин ${shot ?? '—'})`);
    }
    const alarm = await logDangerAlarm(app, alarms, '8d2595-still');
    if (!alarm) {
      dangerClosed(alarms);
      assert(await app.exists(by.exact('תקין')), `статус «תקין» на ${prev} с мониторинга`);
      const t = await timerSeconds(app);
      assert(t >= prev, `таймер не идёт назад (${prev} → ${t} с)`);
      prev = t;
    }
  }

  assert(!(await movedVisible(app)), `в конце неподвижности нет «${MOVED}» (ни окна, ни события в «היסטוריית אירועים»)`);
  if (alarms.length) console.log(`     [#18bb68, не провал] ложных тревог опасности за ${minutes} мин: ${alarms.length}`);
  await dismissFalseDanger(app);
  await endMonitoring(app);
}
